#include <iostream>
#include <vector>
using namespace std;

vector<long long> build_prefix(const vector<long long>& values) {
    int size = static_cast<int>(values.size());
    vector<long long> prefix(size + 1, 0);
    for (int index = 0; index < size; ++index) {
        prefix[index + 1] = prefix[index] + values[index];
    }
    return prefix;
}

long long range_sum(const vector<long long>& prefix, int left, int right) {
    return prefix[right] - prefix[left];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int size, query_count;
    cin >> size >> query_count;
    vector<long long> values(size);
    for (long long& value : values) {
        cin >> value;
    }
    vector<long long> prefix = build_prefix(values);

    for (int query = 0; query < query_count; ++query) {
        int left, right;
        cin >> left >> right;
        cout << range_sum(prefix, left - 1, right) << '\n';
    }
    return 0;
}

